function MY(x,y){const m=L.mc;if(!m||!m.on||Math.hypot(x-m.x,y-m.y)>L.r*1.5)return false;m.hp--;burst(m.x,m.y,'#fff',16);fx('find',6-m.hp);hap(20);if(m.hp<=0){m.on=0;m.done=1;S.gems=(S.gems|0)+2;S.coins+=50;S.st.myth=(S.st.myth|0)+1;burst(m.x,m.y,'#ffd36b',60);msg(t('m_mythic'));save()}return true}
