function prestige(w,b){if((S.pr[w]|0)>=10){msg(t('m_prestige_max'));return}if(wst(w)<90){msg(t('m_prestige_gold'));return}if(!two(b,t('tap_prestige')))return;
  for(let i=1;i<=50;i++)delete S.stars[w*50+i];S.rk[w]=0;S.pr[w]=(S.pr[w]|0)+1;S.st.pres=(S.st.pres|0)+1;S.gems=(S.gems|0)+3;S.coins+=50*S.pr[w];
  const id=PG[(prTot()-1)%PG.length];let pr=t('m_prestige');if(!S.own[id]){S.own[id]=1;const c=CO.find(c=>c.k===id.split(':')[0]);pr+=t('m_unlocked')+cosName(c.k)+': '+optName(c.i[+id.split(':')[1]][0])}
  save();chk();msg(pr);showMap()}
