  const na=Math.min(1+Math.floor(n/8),4+(o.pr|0))+(boss?1:0);
  let kinds=['still','rev','shape','slow','blink','pulse'];if(!S.cb)kinds.push('hue');if(o.pr)kinds.push('size');
  const av=kinds.slice(0,Math.min(kinds.length,2+Math.floor(n/3)));
