  L={o,n:o.n,th:WD[o.theme%25],sh:o.shift||0,t:0,anim:0,mist:0,found:0,na,run:0,over:0,objs:[],fx:[],amb:[],hint:null,bad:null,shake:0,boss,par:(6+cnt*.9+na*4)*(1+.06*sk('mas')),slowT:0,pulse:0,cmb:0,lf:-9,mod:MD,lay,lim:(6+cnt*.9+na*4)*(1.5+.1*sk('mas')),tp:.8+R()*.7,fh:0,sec:n<3?-1:hash(o.seed+'sec')%4,pu:0,cmx:0,memo:MD.includes('memo')?1:0,obs:MD.includes('memo')?6:0,maxm:Math.ceil(cnt/2),fz:0,rh:MD.includes('rhythm')?1:0,tier:n<51?0:n<101?1:n<201?2:n<401?3:n<701?4:n<1001?5:n<2001?6:7};
  const idx=[];while(idx.length<na){const i=Math.floor(R()*cnt);if(!idx.includes(i))idx.push(i)}
