  const cnts={};
  idx.forEach(i=>{const k=MD.includes('rhythm')?'rhy':av[Math.floor(R()*av.length)];L.objs[i].k=k;cnts[k]=(cnts[k]||0)+1;if(k==='hue')L.objs[i].h+=(R()<.5?-1:1)*shift;if(k==='size')L.objs[i].sc*=.78;if(k==='shape')L.objs[i].v=V1;L.objs[i].rk=R()<.5?0:1});
  L.ev=n<4?'':(h=>h<10?'gold':h<13?'treasure':h<18?'portal':h<22?'rainbow':h<24?'jackpot':h<27?'chaos':h<31?'mystery':h<32?'mythic':'')(hash(o.seed+'ev')%100);
  if(L.ev==='chaos'&&MD.includes('rhythm'))L.ev='';
