function layout(){
  if(!L||!W)return;const top=78+ST,ah=H-top-58-SB,aw=W-16,n=L.objs.length;let best=0,bc=1;const hf=L.lay==='hex'?.5:0;
  for(let c=1;c<=n;c++){const rw=Math.ceil(n/c),cs=Math.min(aw/(c+hf),ah/rw);if(cs>best){best=cs;bc=c}}
  const rows=Math.ceil(n/bc);L.r=best*.42;const ox=8+(aw-(bc+hf)*best)/2,oy=top+(ah-rows*best)/2;
  if(L.lay==='spiral'){const d=Math.sqrt(Math.PI*aw*ah/(4*n));L.r=d*.4;const cx=8+aw/2,cy=top+ah/2;L.objs.forEach((o,i)=>{const q=i*2.39996,m=Math.sqrt((i+.5)/n);o.x=cx+Math.cos(q)*m*(aw/2-L.r);o.y=cy+Math.sin(q)*m*(ah/2-L.r)});return}
  L.objs.forEach((o,i)=>{const rw=Math.floor(i/bc);o.x=ox+(i%bc+.5+(rw%2?hf:0)+o.jx)*best;o.y=oy+(rw+.5+o.jy)*best});
}
