 fail:()=>{const t=AC.currentTime;[392,330,262,196].forEach((f,i)=>tn(f,t+i*.16,.4,'sawtooth',.18))},
 hint:()=>{const t=AC.currentTime;tn(880,t,.5,'sine',.25,0,1320);tn(660,t+.1,.5,'sine',.15,0,990)},
 slow:()=>{const t=AC.currentTime;tn(600,t,.8,'sine',.3,0,150)},
 pulse:()=>{const t=AC.currentTime;tn(300,t,.4,'square',.1,0,900)},
 click:()=>{tn(660,AC.currentTime,.07,'triangle',.22)},
 ach:()=>{const t=AC.currentTime;[784,988,1175,1568].forEach((f,i)=>tn(f,t+i*.09,.4,'sine',.28))},
