function fx(n,a){if(S.sf===0||!ac())return;try{SF[n](a)}catch(e){}}
function hap(p){try{navigator.vibrate&&navigator.vibrate(p)}catch(e){}}
const SC=[[0,2,4,7,9],[0,3,5,7,10],[0,2,4,6,7,9,11],[0,2,3,5,7,9,10],[0,2,4,5,7,9,11],[0,1,4,5,7,8,10]];
function musicStop(){if(mus){clearInterval(mus);mus=null}}
function musicStart(){
  if(S.mu===0||!ac())return;
  const w=L?(L.o.theme||0):0,key=w+'|'+(L?L.mod:'')+(L&&L.boss?'b':'');if(mus&&key===mk)return;mk=key;musicStop();
  const root=110*Math.pow(2,((w*5)%12)/12),sc=SC[w%SC.length],bpm=64+(w*7)%40+(L&&L.mod.includes('time')?18:0)+(L&&L.boss?10:0),beat=60/bpm;
  let nx=AC.currentTime+.1,bar=0,step=0;
  const T1=['triangle','sine','sawtooth','sine','triangle','square'][w%6],T2=['sine','triangle','sine','square','triangle','sine'][(w*5)%6],g1=T1==='sawtooth'||T1==='square'?.5:1,g2=T2==='square'?.5:1;
  const note=(d,o)=>root*Math.pow(2,(sc[d%sc.length]+12*Math.floor(d/sc.length)+(o||0))/12);
  mus=setInterval(()=>{if(!AC)return;while(nx<AC.currentTime+.6){
    if(step%8===0){const base=[0,2,3,1][bar%4];[0,2,4].forEach(k=>tn(note(base+k,12),nx,beat*7.5,T1,.07*g1,mg,0,.9));tn(note(base,0),nx,beat*3.8,'sine',.16,mg);tn(note(base,0),nx+beat*4,beat*3.8,'sine',.14,mg);bar++}
    if(!(L&&L.rh)&&Math.random()<.6)tn(note(Math.floor(Math.random()*8),24),nx,beat*1.5,T2,(.08+Math.random()*.05)*g2,mg);
    if(w%3&&step%2===0){const hat=w%3===1;tn(hat?2400:90,nx,hat?.03:.18,hat?'square':'sine',hat?.018:.2,mg,hat?0:45)}
    nx+=beat/2;step++}},200)
}
addEventListener('pointerdown',()=>{if(ac()&&!mus)musicStart()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.closest('#pw'))fx('click')});
